import {useParams} from "react-router-dom";
import {useEffect,useState} from "react";
import axios from "axios";

export default function GamePage(){
  const {id}=useParams();
  const [game,setGame]=useState(null);

  useEffect(()=>{
    axios.get(`http://localhost:5000/api/games/${id}`)
      .then(res=>setGame(res.data));
  },[id]);

  if(!game) return <h2>Loading...</h2>;

  return(
  <iframe id="game-frame" allowfullscreen="" sandbox="allow-scripts allow-same-origin allow-forms allow-popups allow-presentation" referrerpolicy="no-referrer-when-downgrade" loading="lazy" title="Game Frame" src="https://sudoku-online.github.io/a7/city-bike-stunt-2/"></iframe>
  );
}
